text:
{{
  (() => {
    const sommaPrincipale =
      Rating37.value +
      Rating38.value +
      Rating39.value +
      Rating40.value +
      Rating41.value +
      Rating42.value +
      Rating43.value +
      Rating44.value;

    const sommaGiroMerce =
      Rating45.value +
      Rating46.value;

    if (sommaPrincipale === 0 && sommaGiroMerce === 0) return "";

    return (sommaPrincipale === 24 && sommaGiroMerce >= 4)
      ? "IDONEO"
      : "NON IDONEO";
  })()
}}

textColor:
{{
  (() => {
    const sommaPrincipale =
      Rating37.value +
      Rating38.value +
      Rating39.value +
      Rating40.value +
      Rating41.value +
      Rating42.value +
      Rating43.value +
      Rating44.value;

    const sommaGiroMerce =
      Rating45.value +
      Rating46.value;

    const totale = sommaPrincipale + sommaGiroMerce;

    return totale === 0 ? "" :
      (sommaPrincipale === 24 && sommaGiroMerce >= 4)
        ? "green"
        : "red";
